const catalogCategories = Array.from(new Set(entries.map((item) => item.category))).sort();

export default defineIsland<Record<string, never>>({
  name: "component-browser",
  setup: () => {
    const query = signal("");
    const category = signal("ALL");
    const activeTab = signal("overview");
    const toastVisible = signal(false);
    const dataTableSortKey = signal("service");
    const dataTableSortDirection = signal<"asc" | "desc">("asc");
    if (typeof document !== "undefined" && !document.documentElement.hasAttribute("data-coco-catalog-shortcut")) {
      document.documentElement.setAttribute("data-coco-catalog-shortcut", "true");
      document.addEventListener("keydown", (event: KeyboardEvent) => {
        if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") {
          event.preventDefault();
          document.getElementById("component-catalog-search")?.focus();
        }
      });
    }
    return () => {
      const normalized = query.value.trim().toLowerCase();
      const shown = entries.filter((item) => !normalized || `${item.name} ${item.category} ${item.description} ${item.keywords}`.toLowerCase().includes(normalized));
      const filtered = shown.filter((item) => category.value === "ALL" || item.category === category.value);
      const previewContext: PreviewContext = {
        activeTab: activeTab.value,
        toastVisible: toastVisible.value,
        dataTableSortKey: dataTableSortKey.value,
        dataTableSortDirection: dataTableSortDirection.value,
        activateTab: (id) => { activeTab.value = id; },
        showToast: () => { toastVisible.value = true; },
        hideToast: () => { toastVisible.value = false; },
        sortDataTable: (key, direction) => { dataTableSortKey.value = key; dataTableSortDirection.value = direction; },
      };
      return <section class="official-catalog" id="catalog">
        <div class="catalog-heading"><div><span class="eyebrow">OFFICIAL UI</span><h2>{entries.length} referensi komponen + 1.246 ikon</h2><p>Semua contoh dirender dengan <code>@cocoframe/ui</code> dan <code>@cocoframe/icons</code>; JavaScript browser hanya aktif di dalam island.</p></div><div class="component-catalog-controls"><label class="component-search"><span aria-hidden="true"><MagnifierIcon size={20} /></span><input id="component-catalog-search" type="search" value={query.value} placeholder="Search UI and icons..." aria-label="Search components and icons" onInput={(event: Event) => { query.value = (event.currentTarget as HTMLInputElement).value; }} /><kbd>Ctrl/⌘ K</kbd></label><label class="component-category-filter"><span>Category</span><Select id="component-catalog-category" name="category" value={category.value} onInput={(event: Event) => { category.value = (event.currentTarget as HTMLSelectElement).value; }}><option value="ALL">All categories</option>{catalogCategories.map((name) => <option value={name}>{name}</option>)}</Select></label></div></div>
        <div class="component-result-count" role="status">{filtered.length} dari {entries.length} referensi</div>
        <div class="official-component-list">{filtered.map((item) => <ComponentReference entry={item} context={previewContext} />)}</div>
        {filtered.length === 0 ? <p class="components-empty">Tidak ada komponen yang cocok. Coba “form”, “feedback”, “overlay”, atau “navigation”.</p> : null}
      </section>;
    };
  },
});

function entry(id: string, name: string, category: string, description: string, keywords: string, props: ComponentEntry["props"], code: string, preview: (context: PreviewContext) => CocoNode, importCode?: string): ComponentEntry {
  return { id, name, category, description, keywords, props, code, preview, ...(importCode ? { importCode } : {}) };
}

function ComponentReference({ entry: item, context }: { readonly entry: ComponentEntry; readonly context: PreviewContext }) {
  return <article class="official-component" id={item.id}><header><div><span>{item.category}</span><h2>{item.name}</h2><p>{item.description}</p></div><code>{item.importCode ?? `import { ${item.name} } from "@cocoframe/ui"`}</code></header><div class="component-reference-grid"><section class="component-preview"><h3>Preview</h3><div class="component-preview-stage">{item.preview(context)}</div></section><section class="component-source"><h3>Usage</h3><SyntaxHighlighter code={item.code} language="tsx" label={`${item.name} usage example`} /></section></div><section class="component-props"><h3>Props</h3><div role="table" aria-label={`${item.name} props`}><div role="row"><strong>Prop</strong><strong>Type</strong><strong>Default</strong></div>{item.props.map(([name, type, defaultValue]) => <div role="row"><code>{name}</code><code>{type}</code><span>{defaultValue}</span></div>)}</div></section><a class="guide-top" href="#top">Kembali ke atas <span aria-hidden="true"><ArrowUpIcon size={14} /></span></a></article>;
}

function openNativeDialog(id: string): void {
  const dialog = document.getElementById(id) as HTMLDialogElement | null;
  if (dialog && !dialog.open) dialog.showModal();
}

function closeNativeDialog(id: string): void {
  const dialog = document.getElementById(id) as HTMLDialogElement | null;
  if (dialog?.open) dialog.close();
}
